namespace alb {
    struct block {
        void* ptr = nullptr;
        size_t length = 0;
        explicit operator bool() const { return ptr != nullptr; }
        void reset() { ptr = nullptr; length = 0; }
    };
}

namespace alb {
namespace stack_allocator_impl {

bool owns(const void* data, size_t max_size, const block& b) {
    if (b.ptr == nullptr) {
        return false;
    }

    const char* buffer_start = static_cast<const char*>(data);
    const char* buffer_end = buffer_start + max_size;
    const char* block_ptr = static_cast<const char*>(b.ptr);

    return (block_ptr >= buffer_start) && (block_ptr < buffer_end);
}

} // namespace stack_allocator_impl
} // namespace alb

